mapper.select:
SELECT * FROM repair_script
WHERE deleted = 0

    AND script_no LIKE CONCAT('%', #{query.scriptNo}, '%')


    AND script_name LIKE CONCAT('%', #{query.scriptName}, '%')


    AND script_type = #{query.scriptType}


    AND status = #{query.status}


    AND business_system LIKE CONCAT('%', #{query.businessSystem}, '%')


    AND applicant LIKE CONCAT('%', #{query.applicant}, '%')


    AND create_time >= #{query.startTime}


    AND create_time <= #{query.endTime}

ORDER BY create_time DESC
